const EmptyState = ({
  title = "Bring your team on board",
  description = "Invite owners, editors, and reviewers by email or share a secure link collaboration starts the moment they join.",
  inviteLink = "https://app.shadcnspace.com/invite/2f9a7c1e",
  primaryAction = {
    label: "Invite member",
    icon: <Plus className="size-4" />,
  },
  secondaryAction = {
    label: "Copy invite link",
    icon: <Copy className="size-4" />,
  },
}: EmptyStateProps) => {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { once: true, amount: 0.2 });
  const [copied, setCopied] = useState(false);

  const handleCopyClick = async () => {
    try {
      await navigator.clipboard.writeText(inviteLink);
      setCopied(true);
      window.setTimeout(() => setCopied(false), COPIED_RESET_MS);
    } catch {
      // Clipboard access denied or unavailable — no feedback shown.
    }
    secondaryAction?.onClick?.();
  };

  return (
    <div
      ref={ref}
      className="flex w-full items-center justify-center px-4 py-10 sm:py-16"
    >
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate={isInView ? "show" : "hidden"}
        className="flex w-92 max-w-full flex-col items-center gap-6"
      >
        <Empty className="gap-4 border-none p-0">
          <EmptyHeader className="gap-4">
            <motion.div variants={itemVariants}>
              <EmptyMedia variant="default" className="mb-0">
                <EmptyStateIllustration />
              </EmptyMedia>
            </motion.div>
            <motion.div
              variants={itemVariants}
              className="flex flex-col items-center gap-0.5"
            >
              <EmptyTitle className="text-lg font-medium text-foreground">
                {title}
              </EmptyTitle>
              <EmptyDescription className="text-center">
                {description}
              </EmptyDescription>
            </motion.div>
          </EmptyHeader>
          <motion.div variants={itemVariants}>
            <EmptyContent>
              <div className="flex items-start gap-3">
                {primaryAction && (
                  <motion.div
                    whileHover={{ scale: 1.03 }}
                    whileTap={{ scale: 0.97 }}
                    transition={{ duration: 0.2, ease: EASE }}
                    className="inline-flex"
                  >
                    <Button
                      size="lg"
                      onClick={primaryAction.onClick}
                      className="cursor-pointer px-4 hover:bg-primary/80"
                    >
                      {primaryAction.icon}
                      {primaryAction.label}
                    </Button>
                  </motion.div>
                )}
                {secondaryAction && (
                  <motion.div
                    whileHover={{ scale: 1.03 }}
                    whileTap={{ scale: 0.97 }}
                    transition={{ duration: 0.2, ease: EASE }}
                    className="inline-flex"
                  >
                    <Button
                      variant="outline"
                      size="lg"
                      onClick={handleCopyClick}
                      className={cn(
                        "relative cursor-pointer overflow-hidden px-4 transition-colors duration-300",
                        copied &&
                          "border-teal-400/50 dark:border-teal-400/50 text-teal-400 dark:text-teal-400 hover:text-teal-400",
                      )}
                    >
                      <motion.span
                        aria-hidden="true"
                        className="absolute inset-0 origin-left bg-teal-400/25"
                        initial={false}
                        animate={{ scaleX: copied ? 1 : 0 }}
                        transition={{
                          duration: copied ? COPIED_RESET_MS / 1000 : 0.2,
                          ease: copied ? "linear" : EASE,
                        }}
                      />
                      <span className="relative z-10 inline-flex items-center gap-1.5">
                        <AnimatePresence mode="wait" initial={false}>
                          <motion.span
                            key={copied ? "copied" : "copy"}
                            initial={{ opacity: 0, scale: 0.5 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.5 }}
                            transition={{ duration: 0.15, ease: EASE }}
                            className="inline-flex"
                          >
                            {copied ? (
                              <Check className="size-4" />
                            ) : (
                              secondaryAction.icon
                            )}
                          </motion.span>
                        </AnimatePresence>
                        {copied ? "Copied!" : secondaryAction.label}
                      </span>
                    </Button>
                  </motion.div>
                )}
              </div>
            </EmptyContent>
          </motion.div>
        </Empty>
      </motion.div>
    </div>
  );
};

export default EmptyState;
